#include "ship_hull_contact_geometry.hpp"
#include <sys/resource.h>
#include <ctime>
#include "ship_wood_surface_profiles.hpp"
#include "rdf.h"
#include <fstream>
#include <iostream>
#include <chrono>
#include <cassert>
#include <iomanip>
using namespace storm_ship_laser;
template<class T>std::vector<T>read(std::ifstream&f,size_t n){std::vector<T>v(n);f.read(reinterpret_cast<char*>(v.data()),n*sizeof(T));assert(f);return v;}
size_t count(const Mesh&m){size_t n=0;for(const auto&o:m)n+=o.second.size();return n;}
int main(int argc,char**argv){assert(argc==2);std::ifstream f(argv[1],std::ios::binary);assert(f);const auto h=read<RDF_HEAD>(f,1)[0];assert(h.version==RDF_VERSION);const auto names=read<char>(f,h.name_size);read<int32_t>(f,h.names);const auto textures=read<int32_t>(f,h.ntextures);const auto materials=read<RDF_MATERIAL>(f,h.nmaterials);read<RDF_LIGHT>(f,h.nlights);read<RDF_LABEL>(f,h.nlabels);const auto objects=read<RDF_OBJECT>(f,h.nobjects);const auto triangles=read<RDF_TRIANGLE>(f,h.ntriangles);const auto buffers=read<RDF_VERTEXBUFF>(f,h.nvrtbuffs);std::vector<std::vector<uint8_t>>vertices;for(const auto&buffer:buffers)vertices.push_back(read<uint8_t>(f,buffer.size));Mesh original;std::map<int,float>wood;
 std::cout<<std::setprecision(12)<<"GM objects="<<h.nobjects<<" triangles="<<h.ntriangles<<" bboxCenter="<<h.bbox_center.x<<","<<h.bbox_center.y<<","<<h.bbox_center.z<<" bboxSize="<<h.bbox_size.x<<","<<h.bbox_size.y<<","<<h.bbox_size.z<<"\n";
 for(size_t o=0;o<objects.size();++o){const auto&ob=objects[o];auto&out=original[o];const auto&buffer=buffers.at(ob.vertex_buff);unsigned stride=36+(buffer.type&3)*8+(buffer.type>>2)*8;assert(!(buffer.type>>2));for(int n=0;n<ob.ntriangles;++n){Triangle t;for(unsigned j=0;j<3;++j)t[j]=storm_ship_hull::decode(vertices[ob.vertex_buff].data()+size_t(ob.svertex+triangles[ob.striangle+n].vindex[j])*stride,stride);out.push_back(t);}const auto&mat=materials.at(ob.material);const char*texture="";if(mat.texture_type[0]==RDF_TEXTURE_TYPE::TEXTURE_BASE){texture=names.data()+textures.at(mat.texture[0]);const float thickness=storm_ship_wood::thickness("ships/Flyingdutchman1/flyingdutchman1.gm",texture);if(thickness>0)wood[o]=thickness;}std::cout<<"OBJECT "<<o<<" faces="<<out.size()<<" texture="<<texture<<" wood="<<(wood.count(o)?wood.at(o):0)<<"\n";}

 const auto wall=[](auto start){return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();};
 const auto allStart=std::chrono::steady_clock::now();const auto cpuStart=std::clock();auto authored=timberSurface(original,wood);Surface current=storm::ship::material::rebase(authored);current.supportOriginal=storm::ship::material::supportSource(original);auto cells=std::make_shared<MaterialCells>();cells->source=storm::ship::material::cellSource(authored,wood);current.cells=cells;if(!storm::ship::material::trimReleasedCells(current))return 2;current=storm::ship::material::rebase(std::move(current));
 auto layout=storm_ship_structure::build(authored,wood);current.structure=std::make_shared<const storm_ship_structure::State>(storm_ship_structure::seed(layout,current,wood));std::printf("BOOTSTRAP_SEED wall_ms=%.3f cells=%zu graph=%zu\n",wall(allStart),cells->source->solids.size(),layout->cells.size());std::fflush(stdout);
 const auto cacheStart=std::chrono::steady_clock::now();if(!storm::ship::material::preparePhysicalCache(current))return 3;std::printf("BOOTSTRAP_CACHE wall_ms=%.3f\n",wall(cacheStart));std::fflush(stdout);
 auto contact=storm::ship::material::prepareContactMaterial({current.cells,current.structure,0},storm::ship::material::identityContactTransform());if(!contact)return 4;
 const auto volume=[](const Surface&s){double v=0;for(uint32_t id=0;id<s.cells->source->solids.size();++id)v+=closedCutVolume(materialCell(*s.cells,id));return v;};const double before=volume(current);
 Triangle hit{};float largest=0;for(const auto&o:original)if(wood.count(o.first))for(const auto&t:o.second){const auto normal=storm_ship_hull::normalized(storm_ship_hull::cross(t[1].position-t[0].position,t[2].position-t[0].position));const float area=storm_ship_hull::area(t);if(std::abs(normal.x)>.8f&&area>largest){hit=t;largest=area;}}
 if(!largest)return 5;const auto point=(hit[0].position+hit[1].position+hit[2].position)*(1.f/3.f),normal=storm_ship_hull::normalized(storm_ship_hull::cross(hit[1].position-hit[0].position,hit[2].position-hit[0].position));BeamSample beam;beam.start={point.x,point.y,point.z};beam.direction={-normal.x,-normal.y,-normal.z};const auto tangent=beamTangent(beam);beam.tangent={tangent.x,tangent.y,tangent.z};beam.depth=.035f*24.f;
 Input input;input.surface=std::make_shared<const Surface>(current);input.structure=current.structure;input.wood=wood;input.plane.normal=normal*-1.f;input.plane.beams={beam};input.plane.charred=true;input.fragmentLimit=8;input.enclosedFragments=true;input.realizeMechanicalCrush=true;input.closedVolume=closedVolume(canonicalMesh(current));input.generation=42;input.fingerprint=storm::ship::material::fingerprint(original,wood);for(const auto&w:wood)for(const auto&t:original.at(w.first))input.structuralArea+=storm_ship_hull::area(t);auto collision=indexFaces(renderMesh(current));std::vector<uint32_t>ids;collision.broadphase.queryBounds(beamBounds(beam),ids);input.physicalContact=!ids.empty();
 const auto ray=[&](const Mesh&m){float fraction=2;const auto a=point+normal*.2f,b=point-normal*.6f;for(const auto&o:m)if(wood.count(o.first))for(const auto&t:o.second){float u,v;const float at=trace(t,a,b,u,v);if(at>=0&&at<1)fraction=std::min(fraction,at);}return fraction;};const float rayBefore=ray(renderMesh(current));
 std::printf("INPUT point=%a,%a,%a direction=%a,%a,%a radius=%a depth=%a material_volume=%.12f physical_contact=%d bootstrap_ms=%.3f\n",point.x,point.y,point.z,-normal.x,-normal.y,-normal.z,beam.radius,beam.depth,before,input.physicalContact,wall(allStart));std::fflush(stdout);
 const auto prepareStart=std::chrono::steady_clock::now();Projection projected;if(!storm::ship::material::prepare(input,projected))return 6;const double prepareMs=wall(prepareStart);std::printf("CUT prepared_ms=%.3f changed=%d fragments=%zu\n",prepareMs,projected.result.changed,projected.result.fragments.size());std::fflush(stdout);
 const auto projectStart=std::chrono::steady_clock::now();storm::ship::material::prepareContactProjection(input,projected,storm::ship::material::identityContactTransform());const double projectMs=wall(projectStart);const double after=projected.kept?volume(*projected.kept):before;double fragments=0;for(const auto&piece:projected.fragmentRender)fragments+=closedCutVolume(piece);const float rayAfter=ray(projected.render);rusage usage{};getrusage(RUSAGE_SELF,&usage);std::printf("RESULT project_ms=%.3f worker_ms=%.3f cpu_ms=%.3f peak_bytes=%ld changed=%d fragments=%zu before=%.12f after=%.12f emitted=%.12f ablated=%.12f opening_area=%.12f ray_before=%.9f ray_after=%.9f canonical_faces=%zu digest=%llu\n",projectMs,wall(allStart),1000.*double(std::clock()-cpuStart)/CLOCKS_PER_SEC,usage.ru_maxrss,projected.result.changed,projected.result.fragments.size(),before,after,fragments,before-after-fragments,[&]{double a=0;for(const auto&o:projected.result.openings)a+=o.area;return a;}(),rayBefore,rayAfter,count(projected.canonical),(unsigned long long)storm::ship::material::fingerprint(projected.canonical,wood));
 return projected.result.changed&&before>after+fragments&&rayBefore<.3f&&rayAfter>.8f?0:7;
}
